const safeAll = name => { try { return $(name).all(); } catch (e) { return []; } };
const redacted = safeAll('Redact Expired Bodies').filter(i => i.json && i.json.id).length;
const stuck = $input.all().filter(i => i.json && i.json.id).map(i => { const f = i.json.fields || i.json; return { id: i.json.id || '', message_id: f.message_id || '', processing_status: f.processing_status || '', received_at: f.received_at || '', subject: f.subject || '' }; });
const failed = stuck.filter(r => r.processing_status === 'failed');
const review = stuck.filter(r => r.processing_status === 'review_required');
const unprocessed = stuck.filter(r => r.processing_status === 'received');
let report = 'Retention & Health Sweep — ' + new Date().toDateString() + '\n\n';
report += 'Records redacted (text_body and summary cleared): ' + redacted + '\n';
report += 'Failed records: ' + failed.length + '\n';
report += 'Open review_required records: ' + review.length + '\n';
report += 'Unprocessed (received) records: ' + unprocessed.length + '\n';
if (failed.length) { report += '\nFailed (need replay):\n' + failed.map(r => '  • ' + r.message_id + ' — ' + r.subject).join('\n'); }
if (review.length) { report += '\nOpen reviews (need human action):\n' + review.map(r => '  • ' + r.message_id + ' — ' + r.subject).join('\n'); }
return [{ json: { report_text: report, redacted_count: redacted, failed_count: failed.length, review_count: review.length, unprocessed_count: unprocessed.length, failed_records: failed, review_records: review } }];

const r = $('Build Health Report').first().json || {};
const sendNode = $('Send Health Report');
const sendErr = sendNode.all().length && sendNode.first().json.error ? String(sendNode.first().json.error) : '';
return [{ json: {
  redacted_count: r.redacted_count,
  failed_count: r.failed_count,
  review_count: r.review_count,
  unprocessed_count: r.unprocessed_count,
  report_delivered: !sendErr,
  delivery_error: sendErr,
  final_status: sendErr ? 'report_delivery_failed' : 'sweep_complete'
}}];
